int CHotSeatDlg::OnWidgetDeselect(int id, unsigned char* bExitFlag)
{
    switch (id) {
    case OKAY_ID:
        if (OnOK()) {
            *bExitFlag = 1;
            gpWindowManager->dialogReturn = DIALOG_RETURN_OK;
        }
        break;

    case BACK_ID:
        *bExitFlag = 1;
        gpWindowManager->dialogReturn = DIALOG_RETURN_CANCEL;
        return 1;
    }

    return 0;
}

